package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test(expected = IllegalArgumentException.class)
    public void testFactorialDouble_NegativeInput() {
        // Tests the branch: if (n < 0) { throw new IllegalArgumentException(...) }
        MathUtils.factorialDouble(-1);
    }

    @Test
    public void testFactorialDouble_Zero() {
        // Tests the branch: n >= 0 and return Math.floor(Math.exp(factorialLog(n)) + 0.5)
        // 0! = 1
        assertEquals(1.0, MathUtils.factorialDouble(0), DELTA);
    }

    @Test
    public void testFactorialDouble_SmallPositive() {
        // Tests the branch: n >= 0 and return Math.floor(Math.exp(factorialLog(n)) + 0.5)
        // 5! = 120
        assertEquals(120.0, MathUtils.factorialDouble(5), DELTA);
    }

    @Test
    public void testFactorialDouble_LargePositive() {
        // Tests higher range calculations
        // 10! = 3628800
        assertEquals(3628800.0, MathUtils.factorialDouble(10), DELTA);
    }

    /**
     * Note: The provided source code contains a logical contradiction/dead code:
     * if (n < 0) { throw ... }
     * if (n < -21) { return factorial(n); }
     * 
     * Since the first condition catches all n < 0, the second condition (n < -21) 
     * is unreachable in standard execution. However, to aim for maximum coverage 
     * in a coverage tool, we must acknowledge that the branch n < -21 
     * cannot be hit if the first check is present.
     * 
     * If this were a real-world scenario where the code was meant to be 
     * 'if (n < 0 && n < -21)', we would test it. Given the current implementation,
     * we test the exception for negative values.
     */
}
